export const GLOSSARY = [
 ['Rechtsgeschäft','Rechtlich bedeutsame Handlung, die ihre Rechtswirkung durch mindestens eine Willenserklärung herbeiführt.'],
 ['Willenserklärung','Äußerung eines Willens, die auf eine Rechtsfolge gerichtet ist.'],
 ['Angebot','Verbindlicher Antrag auf Abschluss eines Vertrags mit den wesentlichen Vertragsbestandteilen.'],
 ['Annahme','Einverständnis mit einem Angebot, ohne wesentliche Abweichungen.'],
 ['Wirksam','Das Rechtsgeschäft entfaltet die beabsichtigten rechtlichen Wirkungen.'],
 ['Nichtigkeit','Das Rechtsgeschäft entfaltet grundsätzlich von Anfang an keine beabsichtigte Rechtswirkung.'],
 ['Anfechtbarkeit','Ein zunächst wirksames Rechtsgeschäft kann durch wirksame Anfechtung rückwirkend als nichtig gelten.'],
 ['Geschäftsunfähigkeit','Fehlende Fähigkeit, selbst wirksame Willenserklärungen abzugeben, insbesondere bei Kindern unter sieben Jahren.'],
 ['Beschränkte Geschäftsfähigkeit','Geschäftsfähigkeit Minderjähriger zwischen sieben und siebzehn Jahren mit gesetzlichen Schranken.'],
 ['Schwebend unwirksam','Die Wirksamkeit eines Geschäfts hängt noch von einer erforderlichen Genehmigung ab.'],
 ['Gesetzliches Verbot','Rechtsnorm, deren Verletzung zur Nichtigkeit nach § 134 BGB führen kann.'],
 ['Sittenwidrigkeit','Verstoß gegen grundlegende Wertmaßstäbe; kann nach § 138 BGB zur Nichtigkeit führen.'],
 ['Wucher','Sittenwidriges Ausnutzen einer besonderen Lage bei auffälligem Missverhältnis zwischen Leistung und Gegenleistung.'],
 ['Formmangel','Missachtung einer gesetzlich vorgeschriebenen Form; kann zur Nichtigkeit führen.'],
 ['Scherzgeschäft','Nicht ernst gemeinte Erklärung im Erwartungshorizont, dass die mangelnde Ernstlichkeit erkannt wird.'],
 ['Scheingeschäft','Eine einverständlich nur zum Schein abgegebene Willenserklärung.'],
 ['Erklärungsirrtum','Unbewusstes Auseinanderfallen von Gewolltem und tatsächlich Erklärtem, etwa Vertippen.'],
 ['Inhaltsirrtum','Irrtum über den Sinn bzw. die Bedeutung der eigenen Erklärung.'],
 ['Übermittlungsirrtum','Eine zur Übermittlung eingesetzte Person oder Einrichtung gibt die Erklärung falsch weiter.'],
 ['Eigenschaftsirrtum','Irrtum über eine verkehrswesentliche Eigenschaft einer Person oder Sache.'],
 ['Motivirrtum','Irrtum über persönliche Beweggründe oder Erwartungen; grundsätzlich kein Anfechtungsgrund.'],
 ['Arglistige Täuschung','Vorsätzliches Hervorrufen oder Aufrechterhalten eines Irrtums zur Herbeiführung einer Willenserklärung.'],
 ['Widerrechtliche Drohung','Rechtlich unzulässiges Inaussichtstellen eines Übels zur Erzwingung einer Willenserklärung.'],
 ['Anfechtungserklärung','Erklärung gegenüber dem richtigen Anfechtungsgegner, durch die das Anfechtungsrecht ausgeübt wird.']
];
