const Q=[];
function add(chapter,topic,type,prompt,data={},afb=2,source='',bonus=false){
 const id = data.id || `${chapter}-${Q.length+1}`;
 const xp = bonus?70:afb===1?24:afb===2?38:54;
 Q.push({id,chapter,topic,type,prompt,afb,source,bonus,xp,...data});
}
const S=(chapter,topic,prompt,options,correct,solution,afb=2,source='',extra={})=>add(chapter,topic,'single',prompt,{options,correct,solution,...extra},afb,source);
const M=(chapter,topic,prompt,options,correct,solution,afb=2,source='',extra={})=>add(chapter,topic,'multi',prompt,{options,correct,solution,...extra},afb,source);
const F=(chapter,topic,prompt,solution,afb=3,source='',bonus=false,extra={})=>add(chapter,topic,'free',prompt,{solution,...extra},afb,source,bonus);
const T=(chapter,topic,prompt,correct,solution,afb=1,source='')=>add(chapter,topic,'truefalse',prompt,{correct,solution},afb,source);
const D=(chapter,topic,prompt,items,groups,solution,afb=2,source='',bonus=false)=>add(chapter,topic,'drag',prompt,{items,groups,solution},afb,source,bonus);
const Z=(chapter,topic,prompt,items,options,solution,afb=2,source='')=>add(chapter,topic,'match',prompt,{items,options,solution},afb,source);
const I=(chapter,topic,prompt,accepted,solution,afb=1,source='')=>add(chapter,topic,'input',prompt,{accepted,solution},afb,source);
const O=(chapter,topic,prompt,items,solution,afb=2)=>add(chapter,topic,'order',prompt,{items,correct:items.map(x=>x.id),solution},afb);

